import { useMemo, useState } from 'react';
import { Flex, Spinner } from '@docs-front/ui';
import {
  CheckCheck,
  ChevronDown,
  ChevronRight,
  CircleAlert,
  Globe
} from 'lucide-react';
import { z } from 'zod';
import {
  TOOL_LABELS,
  TOOL_NAME
} from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatToolPart/DocumentChatToolPart.constants';
import {
  StyledToolContext,
  StyledWebSearchQuery,
  StyledWebSearchResults,
  StyledWebSearchResultItem,
  StyledWebSearchResultTitle,
  StyledWebSearchResultUrl,
  StyledWebSearchToggle
} from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatToolPart/DocumentChatToolPart.style';

const webSearchResultSchema = z.object({
  title: z.string(),
  url: z.string(),
  content: z.string().optional()
});

type WebSearchResult = z.infer<typeof webSearchResultSchema>;

function sanitizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
      return parsed.href;
    }
    return '';
  } catch {
    return '';
  }
}

const webSearchOutputSchema = z.object({
  results: z.array(webSearchResultSchema)
});

function parseToolOutput(output: unknown): Record<string, unknown> | null {
  if (output == null) return null;
  if (typeof output === 'object') return output as Record<string, unknown>;
  if (typeof output === 'string') {
    try {
      return JSON.parse(output) as Record<string, unknown>;
    } catch {
      return null;
    }
  }
  return null;
}

interface DocumentChatToolPartProps {
  toolName: string;
  isDone: boolean;
  isError: boolean;
  isChatActive: boolean;
  input?: unknown;
  output?: unknown;
}

function WebSearchResults({ results }: { results: WebSearchResult[] }) {
  const [isExpanded, setIsExpanded] = useState(false);

  return (
    <StyledWebSearchResults>
      <StyledWebSearchToggle onClick={() => setIsExpanded(!isExpanded)}>
        {isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
        <span>참고 자료 {results.length}건</span>
      </StyledWebSearchToggle>
      {isExpanded &&
        results.map((result, index) => (
          <StyledWebSearchResultItem
            key={`${index}-${result.url}`}
            href={sanitizeUrl(result.url)}
            target="_blank"
            rel="noopener noreferrer"
          >
            <Flex alignItems="center" gap={6}>
              <Globe size={12} style={{ flexShrink: 0 }} />
              <StyledWebSearchResultTitle>
                {result.title}
              </StyledWebSearchResultTitle>
            </Flex>
            <StyledWebSearchResultUrl>{result.url}</StyledWebSearchResultUrl>
          </StyledWebSearchResultItem>
        ))}
    </StyledWebSearchResults>
  );
}

export function DocumentChatToolPart({
  toolName,
  isDone,
  isError,
  isChatActive,
  input,
  output
}: DocumentChatToolPartProps) {
  const isWebSearch = toolName === TOOL_NAME.WEB_SEARCH;
  const isImageTool =
    toolName === TOOL_NAME.GET_IMAGE ||
    toolName === TOOL_NAME.SVG_GENERATE_AGENT ||
    toolName === TOOL_NAME.UPDATE_IMAGE;

  const parsedResults = useMemo(() => {
    if (!isWebSearch || !output) return null;
    const parsed = parseToolOutput(output);
    if (!parsed) return null;
    const result = webSearchOutputSchema.safeParse(parsed);
    return result.success ? result.data.results : null;
  }, [isWebSearch, output]);

  const toolLabel = TOOL_LABELS[toolName];
  if (!toolLabel) return null;

  const query =
    input && typeof input === 'object' && 'query' in input
      ? String((input as { query: string }).query)
      : null;
  const results =
    isDone && !isError && parsedResults ? parsedResults : null;

  const imageName =
    input && typeof input === 'object' && 'image_name' in input
      ? String((input as { image_name: string }).image_name)
      : input && typeof input === 'object' && 'name' in input
        ? String((input as { name: string }).name)
        : null;

  return (
    <Flex direction="column" gap={4}>
      <Flex alignItems="center" $typo="Md_16" gap={8}>
        {isError ? (
          <Flex alignItems="center" $color="error" gap={8}>
            <CircleAlert size={20} />
            <span>{toolLabel.error}</span>
          </Flex>
        ) : isDone ? (
          <Flex alignItems="center" $color="main" gap={8}>
            <CheckCheck size={20} />
            <span>{toolLabel.done}</span>
          </Flex>
        ) : isChatActive ? (
          <Flex alignItems="center" $color="main" gap={8}>
            <Spinner size={20} />
            <span>{toolLabel.loading}</span>
          </Flex>
        ) : (
          <Flex $color="textGray">도구 중단됨</Flex>
        )}
      </Flex>
      {isWebSearch && query && (
        <StyledWebSearchQuery>&ldquo;{query}&rdquo;</StyledWebSearchQuery>
      )}
      {results &&
        (results.length > 0 ? (
          <WebSearchResults results={results} />
        ) : (
          <StyledWebSearchQuery>검색 결과가 없습니다</StyledWebSearchQuery>
        ))}
      {isImageTool && (isDone || isChatActive) && imageName && (
        <StyledToolContext>{imageName}</StyledToolContext>
      )}
    </Flex>
  );
}
