import { Editor, Transforms, Element as SlateElement } from "slate";
import type { HwpxEditor, HwpxElement, HwpxText, PicElement } from "../schema";
import type { DocumentStore } from "../store";
/** 바이너리 → base64 문자열 */
function uint8ToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

/** 파일 확장자 → MIME 타입 */
function mimeFromExt(name: string): string {
  const ext = name.split(".").pop()?.toLowerCase() ?? "";
  const map: Record<string, string> = {
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    gif: "image/gif",
    bmp: "image/bmp",
    webp: "image/webp",
  };
  return map[ext] ?? "image/png";
}

/**
 * 에디터의 이미지를 업데이트한다.
 *
 * WASM 바이너리를 교체하고, Slate의 pic 노드 src를 Transforms.setNodes로 변경하여
 * history에 기록한다. reloadEditor를 호출하지 않으므로 undo/redo가 정상 동작한다.
 */
export function updateEditorImage(
  editor: HwpxEditor,
  store: DocumentStore,
  data: Uint8Array,
  imageName: string,
): void {
  store.updateImageData(data, imageName);

  // pic 노드를 찾아 update action 적용 → WASM auto-sizing 트리거
  type SlateNode = HwpxElement | HwpxText;
  let picRefId: string | null = null;
  const stack: SlateNode[] = [...editor.children as SlateNode[]];
  while (stack.length > 0) {
    const node = stack.pop()!;
    if (
      "type" in node &&
      node.type === "pic" &&
      "name" in node &&
      node.name === imageName &&
      "refId" in node &&
      node.refId
    ) {
      picRefId = node.refId;
      break;
    }
    if ("children" in node) {
      stack.push(...(node.children as SlateNode[]));
    }
  }
  if (picRefId) {
    store.applyActions([
      {
        type: "update",
        refId: picRefId,
        actionNode: `<pic name="${imageName}"/>`,
      },
    ]);
    store.refreshRefIds();
  }

  const newSrc = `data:${mimeFromExt(imageName)};base64,${uint8ToBase64(data)}`;

  const picEntries = Editor.nodes<PicElement>(editor, {
    at: [],
    match: (n) =>
      SlateElement.isElement(n) && n.type === "pic" && "name" in n && (n as PicElement).name === imageName,
  });

  for (const [, path] of picEntries) {
    Transforms.setNodes(editor, { src: newSrc } as Partial<PicElement>, {
      at: path,
    });
  }
}
