import {
  useCallback,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
  forwardRef
} from 'react';
import type { Ref } from 'react';
import { z } from 'zod';
import { useChat } from '@ai-sdk/react';
import { Flex, Spinner } from '@docs-front/ui';
import { MessagesSquare } from 'lucide-react';
import {
  useMutation,
  useQueryClient,
  useSuspenseQuery
} from '@tanstack/react-query';
import {
  DocumentChatTransport,
  prepareSendMessagesRequest
} from '@/ai/document-chat/document-chat-transport';
import {
  postDocumentChatSession,
  postDocumentChatMessages,
  getDocumentChatGeneratedImage
} from '@/api/document-chat';
import { DocumentChatTextPart } from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatTextPart/DocumentChatTextPart';
import { DocumentChatToolPart } from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatToolPart/DocumentChatToolPart';
import {
  TOOL_LABELS,
  TOOL_NAME
} from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatToolPart/DocumentChatToolPart.constants';
import { getDocumentChatMessagesOptions } from '@/query/options/products';
import type { DocumentChatInputSubmitData } from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatInput/DocumentChatInput';
import { FileCardList } from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatInput/FileCard/FileCard';
import { isPresignedUrlExpired } from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatInput/file-type-utils';
import {
  StyledChatSectionContainer,
  StyledChatSectionContent,
  StyledChatSectionContentScroll,
  StyledChatInputContainer,
  StyledChatEmptyState,
  StyledUserMessageBubble,
  StyledUserMessageContent
} from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatSection.style';
import { DocumentChatInput } from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatInput/DocumentChatInput';
import { useInitializeDocumentChatMessages } from '@/ai/document-chat/hooks/useInitializeDocumentChatMessages';
import { useDocumentChatAutoScrollEffectRef } from '@/ai/document-chat/hooks/useDocumentChatAutoScrollRefEffect';
import { DocumentChatErrorState } from '@/routes/_authenticated/d/-components/DocumentChatSection/DocumentChatErrorState/DocumentChatErrorState';
import { EditorFeedbackPrompt } from '@/routes/_authenticated/d/-components/DocumentChatSection/EditorFeedbackPrompt/EditorFeedbackPrompt';
import type {
  DocshuntDocumentChatUIMessage,
  DocshuntDocumentChatUIMessagePart,
  HwpxAction
} from '@/ai/document-chat/ui-message';
import type { EditorSelection } from '@docs-front/hwpx-editor';
import { lastAssistantMessageIsCompleteWithToolCalls } from 'ai';

export interface DocumentChatSectionHandle {
  finishReview: () => void;
}

interface DocumentChatSectionProps {
  productFileId: string;
  isStatusCompleted: boolean;
  onActionStart?: () => void;
  onAction?: (action: HwpxAction) => void;
  onActionDone?: () => void;
  onAbortStreaming?: () => void;
  onImageUpdate?: (data: Uint8Array, imageName: string) => void;
  onDocumentSave?: () => Promise<void>;
  editorSelection?: EditorSelection | null;
}

export const DocumentChatSection = forwardRef(function DocumentChatSection(
  {
    productFileId,
    isStatusCompleted,
    onActionStart,
    onAction,
    onActionDone,
    onAbortStreaming,
    onImageUpdate,
    onDocumentSave,
    editorSelection
  }: DocumentChatSectionProps,
  ref: Ref<DocumentChatSectionHandle>
) {
  const queryClient = useQueryClient();
  const [pendingReview, setPendingReview] = useState(false);
  const sessionIdRef = useRef<string | null>(null);
  const processedToolCallIdsRef = useRef<Set<string>>(new Set());
  const processingToolCallCountRef = useRef(0);
  const hasErrorRef = useRef(false);

  const {
    data: { messages: initialMessages }
  } = useSuspenseQuery(getDocumentChatMessagesOptions(productFileId));

  const { mutate: postChatMessagesMutate } = useMutation({
    mutationFn: ({
      fileId,
      chatMessage
    }: {
      fileId: string;
      chatMessage: string[];
    }) => postDocumentChatMessages(fileId, { chatMessage }),
    onSuccess: (_, { fileId }) => {
      queryClient.invalidateQueries({
        queryKey: getDocumentChatMessagesOptions(fileId).queryKey
      });
    }
  });

  const transport = useMemo(
    () =>
      new DocumentChatTransport({
        api: `${import.meta.env.VITE_API_URL}/document-chat/messages:stream`,
        prepareSendMessagesRequest
      }),
    []
  );

  const chat = useChat<DocshuntDocumentChatUIMessage>({
    id: `document-chat-${productFileId}`,
    transport,
    messages: initialMessages,
    onError: (error) => {
      console.error('Chat error:', error);
      hasErrorRef.current = true;
      setPendingReview(false);
      onAbortStreaming?.();
    },
    onFinish: ({ messages, isError, isAbort }) => {
      if (isError) {
        return;
      }

      if (isAbort) {
        setPendingReview(false);
        onAbortStreaming?.();
      }

      postChatMessagesMutate({
        fileId: productFileId,
        chatMessage: messages.map((message) => JSON.stringify(message))
      });
    },
    onData: ({ type, data }) => {
      switch (type) {
        case 'data-action': {
          switch (data.phase) {
            case 'start':
              setPendingReview(true);
              onActionStart?.();
              break;
            case 'delta':
              onAction?.(data.action);
              break;
            case 'done':
              onActionDone?.();
              break;
          }
          break;
        }
      }
    },
    sendAutomaticallyWhen: (args) =>
      !hasErrorRef.current &&
      processingToolCallCountRef.current === 0 &&
      lastAssistantMessageIsCompleteWithToolCalls(args),
    onToolCall: async ({ toolCall }) => {
      if (processedToolCallIdsRef.current.has(toolCall.toolCallId)) return;
      processedToolCallIdsRef.current.add(toolCall.toolCallId);

      processingToolCallCountRef.current += 1;
      try {
        if (toolCall.toolName === TOOL_NAME.UPDATE_IMAGE) {
          const { image_name } = z
            .object({
              image_name: z
                .string()
                .min(1)
                .regex(/^[a-zA-Z0-9._-]+$/)
            })
            .parse(toolCall.input);
          const sessionId = sessionIdRef.current;
          if (sessionId) {
            const bytes = await getDocumentChatGeneratedImage(
              sessionId,
              image_name
            );
            onImageUpdate?.(bytes, image_name);
            await onDocumentSave?.();
            addToolOutput({
              tool: toolCall.toolName,
              toolCallId: toolCall.toolCallId,
              output: {
                status: 'success',
                image_name
              }
            });
          }
        }
      } catch {
        addToolOutput({
          tool: toolCall.toolName,
          toolCallId: toolCall.toolCallId,
          state: 'output-error',
          errorText: 'Error occured'
        });
      } finally {
        processingToolCallCountRef.current -= 1;
      }
    }
  });

  const {
    messages,
    setMessages,
    sendMessage,
    status,
    stop,
    error,
    regenerate,
    addToolOutput
  } = chat;

  useInitializeDocumentChatMessages(chat, initialMessages);

  useImperativeHandle(
    ref,
    () => ({
      finishReview: () => {
        const sessionId = sessionIdRef.current;
        if (!sessionId) return;

        setPendingReview(false);

        sendMessage(undefined, {
          body: {
            fileId: productFileId,
            sessionId
          }
        });
      }
    }),
    [sendMessage, productFileId]
  );

  const onSubmit = useCallback(
    async (data: DocumentChatInputSubmitData) => {
      if (pendingReview) return;

      const { sessionId } = await postDocumentChatSession(productFileId);
      sessionIdRef.current = sessionId;
      processedToolCallIdsRef.current.clear();
      hasErrorRef.current = false;

      const parts: DocshuntDocumentChatUIMessagePart[] = [];

      for (const file of data.uploadedFiles) {
        parts.push({
          type: 'file',
          mediaType: file.mediaType,
          filename: file.filename,
          url: file.url
        });
      }

      setMessages(initialMessages);

      parts.push({ type: 'text', text: data.prompt });

      sendMessage(
        { role: 'user', parts },
        {
          body: {
            fileId: productFileId,
            sessionId
          }
        }
      );
    },
    [sendMessage, setMessages, initialMessages, productFileId, pendingReview]
  );

  const onRetry = useCallback(() => {
    hasErrorRef.current = false;
    regenerate({
      body: {
        fileId: productFileId,
        sessionId: sessionIdRef.current
      }
    });
  }, [regenerate, productFileId]);

  const autoScrollRef = useDocumentChatAutoScrollEffectRef(chat);

  return (
    <StyledChatSectionContainer>
      <StyledChatSectionContent>
        <StyledChatSectionContentScroll ref={autoScrollRef}>
          {messages.length === 0 ? (
            <StyledChatEmptyState>
              <MessagesSquare size={40} />
              <span>문서에 대해 질문해보세요</span>
            </StyledChatEmptyState>
          ) : (
            messages.map((message, messageIndex) => (
              <Flex direction="column" key={message.id} gap={8}>
                {message.role === 'user' ? (
                  <StyledUserMessageBubble>
                    <StyledUserMessageContent>
                      <FileCardList
                        files={message.parts
                          .filter((p) => p.type === 'file')
                          .map((p) => ({
                            name:
                              'filename' in p
                                ? ((p.filename as string) ?? '')
                                : '',
                            expired:
                              'url' in p && typeof p.url === 'string'
                                ? isPresignedUrlExpired(p.url)
                                : false
                          }))}
                      />
                      {message.parts.map((part, index) => {
                        if (part.type !== 'text') return null;
                        const match = part.text.match(
                          /^\[선택된 내용: ([^\]]+)\]\n?([\s\S]*)$/
                        );
                        if (match) {
                          return (
                            <span key={index}>
                              <span
                                style={{
                                  fontSize: '12px',
                                  color: '#2C81FC',
                                  display: 'block',
                                  marginBottom: '4px'
                                }}
                              >
                                {match[1]}
                              </span>
                              {match[2]}
                            </span>
                          );
                        }
                        return <span key={index}>{part.text}</span>;
                      })}
                    </StyledUserMessageContent>
                  </StyledUserMessageBubble>
                ) : (
                  (() => {
                    const isLastMessage = messageIndex === messages.length - 1;
                    const isChatActive =
                      isLastMessage &&
                      (status === 'streaming' ||
                        status === 'submitted' ||
                        processingToolCallCountRef.current > 0);

                    const renderItems: Array<
                      | { type: 'text'; partIndex: number }
                      | {
                          type: 'tool';
                          partIndex: number;
                          toolName: string;
                          allDone: boolean;
                          isError: boolean;
                          input?: unknown;
                          output?: unknown;
                        }
                    > = [];

                    for (let i = 0; i < message.parts.length; i++) {
                      const part = message.parts[i];
                      if (part.type === 'text') {
                        renderItems.push({ type: 'text', partIndex: i });
                      } else if (
                        part.type === 'dynamic-tool' &&
                        part.toolName in TOOL_LABELS
                      ) {
                        const isDone =
                          part.state === 'output-available' ||
                          part.state === 'output-error';
                        const hasError = part.state === 'output-error';
                        const last = renderItems[renderItems.length - 1];
                        if (
                          last &&
                          last.type === 'tool' &&
                          last.toolName === part.toolName &&
                          TOOL_LABELS[part.toolName]?.mergeable
                        ) {
                          last.allDone = last.allDone && isDone;
                          if (hasError) {
                            last.isError = true;
                          }
                        } else {
                          renderItems.push({
                            type: 'tool',
                            partIndex: i,
                            toolName: part.toolName,
                            allDone: isDone,
                            isError: hasError,
                            input: 'input' in part ? part.input : undefined,
                            output:
                              part.state === 'output-available'
                                ? part.output
                                : undefined
                          });
                        }
                      }
                    }

                    return renderItems.map((item) => {
                      if (item.type === 'text') {
                        const part = message.parts[item.partIndex];
                        return (
                          <DocumentChatTextPart
                            key={item.partIndex}
                            part={part as { type: 'text'; text: string }}
                          />
                        );
                      }
                      return (
                        <DocumentChatToolPart
                          key={item.partIndex}
                          toolName={item.toolName}
                          isDone={item.allDone}
                          isError={item.isError}
                          isChatActive={isChatActive}
                          input={item.input}
                          output={item.output}
                        />
                      );
                    });
                  })()
                )}
              </Flex>
            ))
          )}
          {error && <DocumentChatErrorState onRetry={onRetry} />}
          {status === 'submitted' && (
            <Flex alignItems="center">
              <Spinner size={20} />
            </Flex>
          )}
        </StyledChatSectionContentScroll>
      </StyledChatSectionContent>

      <StyledChatInputContainer>
        <EditorFeedbackPrompt
          assistantMessageCount={
            messages.filter((m) => m.role === 'assistant').length
          }
        />
        <DocumentChatInput
          productFileId={productFileId}
          onSubmit={onSubmit}
          chatStatus={status}
          stop={stop}
          disabled={!isStatusCompleted || pendingReview}
          pendingReview={pendingReview}
          editorSelection={editorSelection}
        />
      </StyledChatInputContainer>
    </StyledChatSectionContainer>
  );
});
