import { Node, Element as SlateElement } from "slate";
import type { HwpxEditor, PicElement } from "../schema";
import type { DocumentStore } from "../store";

/** base64 data URL → Uint8Array 디코딩 */
function dataUrlToUint8Array(dataUrl: string): Uint8Array | null {
  const match = dataUrl.match(/^data:[^;]+;base64,(.+)$/);
  if (!match?.[1]) return null;
  const binary = atob(match[1]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * pic 요소의 src가 변경될 때(undo/redo 포함) WASM 이미지 바이너리를 동기화하는 플러그인.
 *
 * set_node operation에서 pic의 src 변경을 감지하여 base64 data URL을 디코딩한 뒤
 * store.updateImageData()로 WASM에 반영한다.
 */
export function withImageUndo(
  editor: HwpxEditor,
  store: DocumentStore,
): HwpxEditor {
  const { apply } = editor;

  editor.apply = (op) => {
    apply(op);

    if (op.type === "set_node" && "src" in op.newProperties) {
      try {
        const node = Node.get(editor, op.path);
        if (
          SlateElement.isElement(node) &&
          node.type === "pic" &&
          "name" in node
        ) {
          const picNode = node as PicElement;
          const data = dataUrlToUint8Array(picNode.src);
          if (data) {
            store.updateImageData(data, picNode.name);
          }
        }
      } catch {
        /* batch operation 중 path가 유효하지 않을 수 있음 */
      }
    }
  };

  return editor;
}
