import { Spinner } from '@docs-front/ui';
import { basicComponents } from '@/markdown/components/BasigComponents/BasicComponents';
import type { TextUIPart } from 'ai';
import { Streamdown } from 'streamdown';

interface DocumentChatTextPartProps {
  part: TextUIPart;
}

export function DocumentChatTextPart({ part }: DocumentChatTextPartProps) {
  if (part.state === 'streaming' && part.text.length === 0) {
    return <Spinner size={20} />;
  }

  return (
    <div>
      <Streamdown components={basicComponents}>{part.text}</Streamdown>
    </div>
  );
}
